// Completeness check: walks the product API tree (categories -> products ->
// variants) and diffs it against public/sitemap-0.xml, reporting any URL the
// API exposes that didn't make it into the sitemap.
//
// Run AFTER a build (the sitemap is regenerated by `npm run build`):
//   node scripts/check-sitemap.mjs
import axios from "axios";
import fs from "fs";

// Node doesn't auto-load .env, so these mirror the app's fallbacks. Override by
// exporting the vars in your shell before running if you need a different host.
const base =
  process.env.NEXT_PUBLIC_API_BASE_URL ??
  "https://mars-api.mangobeach-29eb5614.ukwest.azurecontainerapps.io/";
const SITE = (process.env.NEXT_PUBLIC_SITE_URL ?? "https://www.marsvalvenok.com").replace(/\/$/, "");
const c = axios.create({ baseURL: base, headers: { "Content-Type": "application/json" } });

// Same category source of truth the build uses.
const catsSrc = fs.readFileSync("src/app/products/data/categories.ts", "utf8");
const CATEGORY_IDS = [...catsSrc.matchAll(/id:\s*"([^"]+)"/g)].map((m) => m[1]);

const expected = new Set();
for (const id of CATEGORY_IDS) {
  expected.add(`${SITE}/products/${id}`);
  let products = [];
  try {
    products = (await c.get(`/api/product/${id}`)).data.products ?? [];
  } catch {
    console.log(`  ! catalog ${id} failed to load`);
    continue;
  }
  for (const p of products) {
    expected.add(`${SITE}/products/${id}/${p.id}`);
    try {
      const variants = (await c.get(`/api/product/${p.id}/variants`)).data.variants ?? [];
      for (const v of variants) expected.add(`${SITE}/products/${id}/${p.id}/variants/${v.id}`);
    } catch {
      /* product has no variants (404) — expected for some */
    }
  }
}

const xml = fs.readFileSync("public/sitemap-0.xml", "utf8");
const inSitemap = new Set([...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]));
const missing = [...expected].filter((u) => !inSitemap.has(u));

console.log(`Expected (from API):  ${expected.size}`);
console.log(`In sitemap total:     ${inSitemap.size}`);
console.log(`Missing from sitemap: ${missing.length}`);
if (missing.length) {
  console.log("--- MISSING ---");
  missing.forEach((u) => console.log("  " + u));
  process.exit(1);
} else {
  console.log("✅ Every product/variant URL the API exposes is in the sitemap.");
}
